insert into huong_dan (muc, noi_dung, ghi_chu) values
  ('Tên bộ dữ liệu', 'Sổ tay thiết kế điện nhà phố Việt Nam 2–5 tầng', 'Bản khởi tạo dữ liệu, cần kỹ sư điện kiểm tra'),
  ('Cấu trúc nguồn', 'Dựa trên 5 nhóm trong playbook mẫu văn phòng Bắc Mỹ', 'Phần cáp trong mẫu không có dữ liệu nên được xây mới'),
  ('Phạm vi', 'Nhà ở riêng lẻ 2–5 tầng tại Việt Nam', 'Không mặc định áp dụng cho nhà ở kết hợp kinh doanh hoặc công trình đặc biệt'),
  ('Dữ liệu giả định', 'Các mức công suất, số lượng, cao độ, tiết diện, thứ tự ưu tiên là giá trị tham khảo', 'Không phải giá trị bắt buộc của tiêu chuẩn'),
  ('Nguồn điện', 'Điện 1 pha / điện 3 pha; điện áp nhập theo hồ sơ cấp điện', 'Không tự mặc định 220/380 hay 230/400 cho mọi công trình'),
  ('Cấu trúc mã', 'Các mã trong workbook là mã nội bộ cho Agent', 'Không phải mã hàng thực tế của hãng'),
  ('Trạng thái kiểm chứng', 'Mọi bản ghi cần người thiết kế điện phê duyệt trước khi tạo hồ sơ thi công', 'Trường tình trạng kiểm chứng: Tham khảo / Cần xác minh / Chờ phê duyệt'),
  ('Phân biệt pháp lý', 'Quy chuẩn bắt buộc trong phạm vi áp dụng; tiêu chuẩn áp dụng theo văn bản liên quan/hợp đồng', 'Xem bảng Nguồn tiêu chuẩn'),
  ('Dây cáp', 'Không gán cố định dòng mang tải theo tiết diện', 'Phải tính theo phương pháp đi dây và các hệ số hiệu chỉnh'),
  ('An toàn', 'Không tự chọn CB, cáp hoặc độ nhạy chống rò nếu thiếu dữ liệu đầu vào', 'Gắn cờ yêu cầu kỹ sư rà soát'),
  ('Trường mô đun', 'Đơn vị mô đun DIN tham khảo, cần đối chiếu catalogue cụ thể', 'Không suy từ số mô đun ra số mạch tuyệt đối'),
  ('Quy tắc nhận diện', 'Từ khóa tiếng Việt để nhận diện đối tượng IFC và gợi ý lớp đấu nối', 'Không tạo tự động khi mức tin cậy thấp'),
  ('Sắp xếp ưu tiên', 'Thứ tự ưu tiên chỉ dùng để xếp danh mục tham khảo', 'Không đồng nghĩa công suất cao nhất là tốt nhất'),
  ('Bảng máy biến áp', 'Không xây danh mục máy biến áp trung thế cho nhà phố thông thường', 'Chỉ làm bảng xác định điều kiện ngoại lệ'),
  ('Ngày xây dựng', '11/11/2026', 'Các tiêu chuẩn cần xác minh lại trước dự án thực tế');
